from collections import deque

def shortest_path_all_keys(grid):
    R, Cn = len(grid), len(grid[0])
    nkeys = 0
    for r in range(R):
        for c in range(Cn):
            ch = grid[r][c]
            if ch == "@":
                sr, sc = r, c
            elif "a" <= ch <= "f":
                nkeys = max(nkeys, ord(ch) - 96)
    target = (1 << nkeys) - 1
    seen = {(sr, sc, 0)}
    q = deque([(sr, sc, 0, 0)])
    while q:
        r, c, m, d = q.popleft()
        if m == target:
            return d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if not (0 <= nr < R and 0 <= nc < Cn):
                continue
            ch = grid[nr][nc]
            if ch == "#":
                continue
            nm = m
            if "a" <= ch <= "f":
                nm |= 1 << (ord(ch) - 97)
            elif "A" <= ch <= "F" and not (m >> (ord(ch) - 65)) & 1:
                continue
            if (nr, nc, nm) not in seen:
                seen.add((nr, nc, nm))
                q.append((nr, nc, nm, d + 1))
    return -1
